import {BY_ID, LIMITS, CATALOG_VERSION, QUESTIONS} from './catalog-v1.js';
export const copy=value=>structuredClone(value);
export function fresh(){return {schemaVersion:1,catalogVersion:CATALOG_VERSION,draft:{name:'',iteration:1,status:'draft',units:[],rationale:Object.fromEntries(QUESTIONS.map(([k])=>[k,'']))},submissions:[]};}
export function totals(units){return units.reduce((s,u)=>{for(const k of Object.keys(LIMITS))s[k]+=BY_ID[u.type].cost[k];return s;},{build:0,operation:0,personnel:0});}
export function freeHosts(units,type,excludeId){const c=BY_ID[type];return units.filter(u=>c.hosts?.includes(u.type)&&!units.some(p=>p.id!==excludeId&&p.type===type&&p.parentId===u.id));}
export function freeSupports(units,type,excludeId){const c=BY_ID[type];return units.filter(u=>u.type===c.support&&!units.some(p=>p.id!==excludeId&&p.supportId===u.id));}
export function issues(units){const errors=[];const ids=new Set();const occupied=new Set();const usedSupports=new Set();
 for(const u of units){const c=BY_ID[u.type];if(!c){errors.push('Unbekannte Karte.');continue;}if(ids.has(u.id))errors.push('Doppelte Einheitenkennung.');ids.add(u.id);
 if(c.unique&&units.filter(x=>x.type===u.type).length>1)errors.push(c.name+' ist nur einmal wählbar.');
 for(const required of c.requires||[])if(!units.some(x=>x.type===required))errors.push(c.name+' benötigt '+BY_ID[required].name+'.');
 if(c.hosts){if(!u.parentId&&!c.optionalHost)errors.push(c.name+' benötigt eine zugeordnete Plattform.');if(u.parentId){const parent=units.find(x=>x.id===u.parentId);if(!parent||!c.hosts.includes(parent.type))errors.push('Ungeeignete Plattform für '+c.name+'.');const key=u.parentId+':'+u.type;if(occupied.has(key))errors.push('Auf dieser Plattform ist bereits ein Paket '+c.name+' zugeordnet.');occupied.add(key);}}
 else if(u.parentId)errors.push(c.name+' kann keiner Plattform zugeordnet werden.');
 if(c.support){const support=units.find(x=>x.id===u.supportId);if(!support||support.type!==c.support)errors.push(c.name+' benötigt ein eigenes Paket '+BY_ID[c.support].name+'.');if(usedSupports.has(u.supportId))errors.push('Ein Logistikpaket kann nur ein Kräftepaket unterstützen.');usedSupports.add(u.supportId);}else if(u.supportId)errors.push('Unerlaubte Unterstützungszuordnung.');
 }return [...new Set(errors)];}
function editable(state){if(state.draft.status!=='draft')throw new Error('Dieser Entwurf ist abgegeben. Beginnt eine Überarbeitung.');}
function checked(state){const errors=issues(state.draft.units);if(errors.length)throw new Error(errors.join(' '));return state;}
export function availability(units,type){const c=BY_ID[type];if(!c)return 'Unbekannte Karte.';if(c.unique&&units.some(u=>u.type===type))return 'Bereits in eurer Flotte.';const missing=(c.requires||[]).filter(id=>!units.some(u=>u.type===id)).map(id=>BY_ID[id].name);if(missing.length)return 'Benötigt: '+missing.join(', ');if(c.hosts&&!c.optionalHost&&!freeHosts(units,type).length)return 'Benötigt eine freie Plattform: '+c.hosts.map(id=>BY_ID[id].name).join(' oder ');if(c.support&&!freeSupports(units,type).length)return 'Benötigt ein freies Paket '+BY_ID[c.support].name;return '';}
export function addUnit(state,type,options={}){editable(state);if(state.draft.units.length>=1000)throw new Error('Maximal 1.000 Bausteine pro Entwurf.');const why=availability(state.draft.units,type);if(why)throw new Error(why);const next=copy(state),c=BY_ID[type];const id=options.id||crypto.randomUUID();
 next.draft.units.push({id,type,parentId:options.parentId??(c.hosts&&!c.optionalHost?freeHosts(next.draft.units,type)[0]?.id:null),supportId:options.supportId??(c.support?freeSupports(next.draft.units,type)[0]?.id:null)});return checked(next);}
export function removeUnit(state,id){editable(state);if(!state.draft.units.some(u=>u.id===id))throw new Error('Einheit nicht gefunden.');const next=copy(state);next.draft.units=next.draft.units.filter(u=>u.id!==id);try{return checked(next);}catch(e){throw new Error('Zuerst abhängige Pakete entfernen oder umordnen. '+e.message);}}
export function assignUnit(state,id,parentId,supportId){editable(state);const next=copy(state),unit=next.draft.units.find(u=>u.id===id);if(!unit)throw new Error('Paket nicht gefunden.');unit.parentId=parentId||null;unit.supportId=supportId||null;return checked(next);}
export function submissionErrors(draft){const errors=issues(draft.units),cost=totals(draft.units);if(!draft.name.trim())errors.push('Gebt eurer Gruppe einen Namen.');if(!draft.units.length)errors.push('Fügt mindestens einen Baustein hinzu.');for(const key of Object.keys(LIMITS))if(cost[key]>LIMITS[key])errors.push(({build:'Aufbaukapital',operation:'Jährlicher Betrieb',personnel:'Personal'})[key]+' überschritten.');for(const [key,label]of QUESTIONS)if(!draft.rationale[key]?.trim())errors.push(label);return errors;}
export function submit(state,now=new Date().toISOString()){editable(state);const errors=submissionErrors(state.draft);if(errors.length)throw new Error(errors.join(' '));const next=copy(state);next.draft.status='submitted';next.submissions.push({...copy(next.draft),submittedAt:now});return next;}
export function revise(state){if(state.draft.status!=='submitted')throw new Error('Gebt zunächst euren aktuellen Entwurf ab.');if(state.submissions.length>=100)throw new Error('Maximal 100 Abgaben. Exportiert diesen Durchgang und beginnt eine neue Gruppe.');const next=copy(state);next.draft.status='draft';next.draft.iteration++;return next;}
export function parseDocument(raw){
 if(!raw||raw.schemaVersion!==1||raw.catalogVersion!==CATALOG_VERSION)throw new Error('Diese Datei gehört nicht zur unterstützten Version des Flottenateliers.');
 const cleanDraft=(d,snapshot=false)=>{if(!d||typeof d.name!=='string'||d.name.length>100||!Number.isSafeInteger(d.iteration)||d.iteration<1||!['draft','submitted'].includes(d.status)||!Array.isArray(d.units)||d.units.length>1000)throw new Error('Ungültiger Entwurf in der Datei.');
 const units=d.units.map(u=>{if(!u||!BY_ID[u.type]||typeof u.id!=='string'||!u.id.length||u.id.length>100||!['parentId','supportId'].every(k=>u[k]===null||typeof u[k]==='string'))throw new Error('Ungültige Einheit in der Datei.');return {id:u.id,type:u.type,parentId:u.parentId,supportId:u.supportId};});
 const errors=issues(units);if(errors.length)throw new Error(errors.join(' '));const rationale={};for(const [key]of QUESTIONS){if(typeof d.rationale?.[key]!=='string'||d.rationale[key].length>5000)throw new Error('Ungültige Begründung in der Datei.');rationale[key]=d.rationale[key];}
 const result={name:d.name,iteration:d.iteration,status:d.status,units,rationale};if(snapshot){if(d.status!=='submitted'||typeof d.submittedAt!=='string'||!Number.isFinite(Date.parse(d.submittedAt))||submissionErrors(result).length)throw new Error('Ungültige Abgabe in der Datei.');result.submittedAt=d.submittedAt;}return result;};
 if(!Array.isArray(raw.submissions)||raw.submissions.length>100)throw new Error('Ungültige Versionsliste.');const draft=cleanDraft(raw.draft),submissions=raw.submissions.map(d=>cleanDraft(d,true));
 if(submissions.some((s,i)=>s.iteration!==i+1))throw new Error('Ungültige Reihenfolge der Abgaben.');
 if(draft.iteration!==submissions.length+(draft.status==='draft'?1:0))throw new Error('Entwurf und Abgaben passen nicht zusammen.');
 if(draft.status==='submitted'){const last=submissions.at(-1);if(!last||JSON.stringify(draft)!==JSON.stringify(Object.fromEntries(Object.entries(last).filter(([k])=>k!=='submittedAt'))))throw new Error('Abgegebener Entwurf wurde nachträglich verändert.');}
 return {schemaVersion:1,catalogVersion:CATALOG_VERSION,draft,submissions};
}

